package br.com.shirokaidex.menus;

import br.com.shirokaidex.config.Settings;
import br.com.shirokaidex.pokedex.*;
import br.com.shirokaidex.rankings.*;
import br.com.shirokaidex.rewards.*;
import br.com.shirokaidex.menus.layout.RewardView;
import br.com.shirokaidex.competitions.CompetitionStore;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.item.*;
import net.minecraft.network.chat.Component;
import java.util.*;
import java.util.function.*;

/** Deliberately limited public navigation requested for the initial server rollout. */
public final class FocusedMenu {
    public static final List<Integer> MILESTONES=List.of(10,25,50,75,90,100);
    private FocusedMenu() { }
    private static final br.com.shirokaidex.localization.Messages TEXT=new br.com.shirokaidex.localization.Messages();
    private static String text(Settings s,String key,Object...args){return TEXT.text(s.language(),"focused."+key,args).getString();}
    private static void card(SimpleContainer c,Map<Integer,Runnable> actions,int slot,Item icon,String name,List<String> lore,Runnable action){ProfileMenu.card(c,slot,icon,Component.literal(name),lore.stream().map(Component::literal).map(x->(Component)x).toList());if(action!=null)actions.put(slot,action);}
    private static void show(ServerPlayer p,Settings s,String title,SimpleContainer c,Map<Integer,Runnable> actions,Runnable back){card(c,actions,c.getContainerSize()-5,Items.ARROW,text(s,"back"),List.of(text(s,"back_hint")),back);MainMenu.show(p,HomeMenu.gradient(title,s.home().palette()),c,actions);}
    public static void home(ServerPlayer p,Settings s,boolean active,Runnable dex,Runnable rankings,Runnable events){var c=new SimpleContainer(27);var a=new HashMap<Integer,Runnable>();card(c,a,11,Items.BOOK,text(s,"dex"),List.of(text(s,"dex_hint")),dex);card(c,a,13,Items.GOLD_INGOT,text(s,"rankings"),List.of(text(s,"rankings_hint")),rankings);card(c,a,15,active?Items.LIME_DYE:Items.GRAY_DYE,text(s,"events"),List.of(active?text(s,"event_open"):text(s,"event_closed")),active?events:null);show(p,s,s.menuTitle(),c,a,p::closeContainer);}
    public static void selector(ServerPlayer p,Settings s,Map<String,ProgressCalculator.CollectionProgress> progress,Consumer<String> choose,Runnable back){var c=new SimpleContainer(27);var a=new HashMap<Integer,Runnable>();var ids=List.of("national","special","shiny");var names=List.of(text(s,"national"),text(s,"special"),text(s,"shiny"));var icons=List.of(Items.BOOK,Items.NETHER_STAR,Items.AMETHYST_SHARD);for(int i=0;i<3;i++){String id=ids.get(i);var value=progress.get(id);card(c,a,10+i*2,icons.get(i),names.get(i),List.of(value==null?"N/D":value.progress().formattedPercentage(s.language()).orElse("N/D")),value==null?null:()->choose.accept(id));}card(c,a,16,Items.DRAGON_EGG,text(s,"forms"),List.of(text(s,"future")),null);show(p,s,text(s,"dex"),c,a,back);}
    public static void collection(ServerPlayer p,Settings s,CollectionDefinition definition,DexProgress progress,List<RewardPlan> plans,Set<String> unlocked,Map<String,RewardJournal.State> states,Consumer<RewardPlan> claim,Runnable wiki,Runnable back){var c=new SimpleContainer(36);var a=new HashMap<Integer,Runnable>();card(c,a,4,Items.SPYGLASS,text(s,"wiki"),List.of(text(s,"wiki_hint"),text(s,"progress",progress.formattedPercentage(s.language()).orElse("N/D"))),wiki);for(int i=0;i<6;i++){int threshold=s.home().milestones().get(i);var plan=plans.stream().filter(r->r.minimumPercent()!=null&&r.minimumPercent().compareTo(java.math.BigDecimal.valueOf(threshold))==0).findFirst().orElse(null);var state=plan==null?null:RewardView.state(unlocked.contains(plan.id()),states.get(plan.id()));var lore=new ArrayList<String>();lore.add(text(s,"threshold",threshold));if(plan==null)lore.add(text(s,"reward_unconfigured"));else {lore.add(TEXT.text(s.language(),"layout.reward_status."+state.status().name()).getString());for(var item:plan.items())lore.add(item.count()+"x "+item.id());if(state.canClaim())lore.add(text(s,"claim"));}card(c,a,10+i,plan==null||!state.canClaim()?Items.GRAY_DYE:Items.CHEST,text(s,"threshold_name",threshold),lore,state!=null&&state.canClaim()?()->claim.accept(plan):null);}show(p,s,definition.name(),c,a,back);}
    public static void rankingRoot(ServerPlayer p,Settings s,Runnable dex,Runnable captures,Runnable defeated,Runnable back){var c=new SimpleContainer(27);var a=new HashMap<Integer,Runnable>();card(c,a,11,Items.BOOK,text(s,"dex_rankings"),List.of(text(s,"dex_rankings_hint")),dex);card(c,a,13,Items.GOLD_INGOT,text(s,"capture_rankings"),List.of(text(s,"capture_rankings_hint")),captures);card(c,a,15,Items.IRON_SWORD,text(s,"defeats"),List.of(text(s,"defeats_hint")),defeated);show(p,s,text(s,"rankings"),c,a,back);}
    public static void boards(ServerPlayer p,Settings s,boolean dex,List<CaptureRanking> definitions,Map<String,CaptureRankings.Page> pages,Runnable back){var c=new SimpleContainer(27);var a=new HashMap<Integer,Runnable>();int i=0;for(var definition:definitions){if(i>=3)break;var lines=new ArrayList<String>();var page=pages.get(definition.id());if(page==null)lines.add("N/D");else if(page.entries().isEmpty())lines.add(text(s,"ranking_empty"));else {int position=1;for(var entry:page.entries()){String score=entry.total()==null?Long.toString(entry.score()):DexProgress.known(entry.total(),entry.registered()).formattedPercentage(s.language()).orElse("N/D");lines.add((position++)+". "+entry.name()+" — "+score);}}card(c,a,10+i++*2,Items.GOLD_INGOT,definition.name(),lines,null);}if(dex)card(c,a,16,Items.DRAGON_EGG,text(s,"forms"),List.of(text(s,"future")),null);show(p,s,dex?text(s,"dex_top"):text(s,"captures_top"),c,a,back);}
    public static void defeated(ServerPlayer p,Settings s,List<br.com.shirokaidex.defeats.DefeatLedger.Entry> entries,Runnable back){var c=new SimpleContainer(27);var a=new HashMap<Integer,Runnable>();var lines=new ArrayList<String>();int rank=1;for(var e:entries)lines.add((rank++)+". "+e.name()+" — "+e.total());if(lines.isEmpty())lines.add(text(s,"defeats_empty"));card(c,a,13,Items.IRON_SWORD,text(s,"defeats_top"),lines,null);show(p,s,text(s,"defeats"),c,a,back);}
    public static void eventBoard(ServerPlayer p,Settings s,br.com.shirokaidex.database.Database.CompetitionView view,Runnable back){var c=new SimpleContainer(27);var a=new HashMap<Integer,Runnable>();var e=view.edition();card(c,a,11,Items.CLOCK,e.definition().name(),List.of(text(s,"start",e.start().atZone(e.definition().timezone()).format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm z"))),text(s,"end",e.end().atZone(e.definition().timezone()).format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm z"))),text(s,"event_rule"),text(s,"event_score",view.membership().score())),null);var lines=new ArrayList<String>();for(var entry:view.standings())lines.add(entry.position()+". "+entry.name()+" — "+entry.score());if(lines.isEmpty())lines.add(text(s,"ranking_empty"));card(c,a,15,Items.GOLD_INGOT,text(s,"event_top"),lines,null);show(p,s,e.definition().name(),c,a,back);}
    public static void events(ServerPlayer p,Settings s,List<CompetitionStore.Edition> editions,Consumer<String> enter,Runnable back){var c=new SimpleContainer(27);var a=new HashMap<Integer,Runnable>();int i=0;for(var e:editions){if(i>=18)break;boolean active=e.state()==CompetitionStore.State.ACTIVE&&java.time.Instant.now().isBefore(e.end());card(c,a,i++,active?Items.LIME_DYE:Items.GRAY_DYE,e.definition().name(),List.of(text(s,"start",e.start().atZone(e.definition().timezone()).format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm z"))),text(s,"end",e.end().atZone(e.definition().timezone()).format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm z"))),active?text(s,"join"):text(s,"closed")),active?()->enter.accept(e.id()):null);}show(p,s,text(s,"capture_events"),c,a,back);}
}
